def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Matching diagonal neighbors define a ray continuing downward in that
    # diagonal direction.
    for r in range(h - 1):
        for c in range(w):
            for dc in (-1, 1):
                c2 = c + dc
                if 0 <= c2 < w and grid[r][c] != background and grid[r][c] == grid[r + 1][c2]:
                    color = grid[r][c]
                    rr, cc = r + 2, c + 2 * dc
                    while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == background:
                        out[rr][cc] = color
                        rr += 1
                        cc += dc
    return out
